    /// <inheritdoc />
    protected override async ValueTask<bool> RegisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case Outline outline:
                if (outline != Outline)
                {
                    Outline = outline;
                    ModifiedParameters[nameof(Outline)] = Outline;
                }
                
                return true;
            case AttributeColorInfo attributes:
                Attributes ??= [];
                if (!Attributes.Contains(attributes))
                {
                    Attributes = [..Attributes, attributes];
                    ModifiedParameters[nameof(Attributes)] = Attributes;
                }
                
                return true;
            case Symbol backgroundFillSymbol:
                if (backgroundFillSymbol != BackgroundFillSymbol)
                {
                    BackgroundFillSymbol = backgroundFillSymbol;
                    ModifiedParameters[nameof(BackgroundFillSymbol)] = BackgroundFillSymbol;
                }
                
                return true;
            case PieChartLegendOptions legendOptions:
                if (legendOptions != LegendOptions)
                {
                    LegendOptions = legendOptions;
                    ModifiedParameters[nameof(LegendOptions)] = LegendOptions;
                }
                
                return true;
            case PieChartOthersCategory othersCategory:
                if (othersCategory != OthersCategory)
                {
                    OthersCategory = othersCategory;
                    ModifiedParameters[nameof(OthersCategory)] = OthersCategory;
                }
                
                return true;
            case VisualVariable visualVariables:
                VisualVariables ??= [];
                if (!VisualVariables.Contains(visualVariables))
                {
                    VisualVariables = [..VisualVariables, visualVariables];
                    ModifiedParameters[nameof(VisualVariables)] = VisualVariables;
                }
                
                return true;
            default:
                return await base.RegisterGeneratedChildComponent(child);
        }
    }

    /// <inheritdoc />
    protected override async ValueTask<bool> UnregisterGeneratedChildComponent(MapComponent child)
    {
        switch (child)
        {
            case Outline _:
                Outline = null;
                ModifiedParameters[nameof(Outline)] = Outline;
                return true;
            case AttributeColorInfo attributes:
                Attributes = Attributes?.Where(a => a != attributes).ToList();
                ModifiedParameters[nameof(Attributes)] = Attributes;
                return true;
            case Symbol _:
                BackgroundFillSymbol = null;
                ModifiedParameters[nameof(BackgroundFillSymbol)] = BackgroundFillSymbol;
                return true;
            case PieChartLegendOptions _:
                LegendOptions = null;
                ModifiedParameters[nameof(LegendOptions)] = LegendOptions;
                return true;
            case PieChartOthersCategory _:
                OthersCategory = null;
                ModifiedParameters[nameof(OthersCategory)] = OthersCategory;
                return true;
            case VisualVariable visualVariables:
                VisualVariables = VisualVariables?.Where(v => v != visualVariables).ToList();
                ModifiedParameters[nameof(VisualVariables)] = VisualVariables;
                return true;
            default:
                return await base.UnregisterGeneratedChildComponent(child);
        }
    }
    
    /// <inheritdoc />
    public override void ValidateRequiredGeneratedChildren()
    {
    
        if (Attributes is not null)
        {
            foreach (AttributeColorInfo child in Attributes)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        BackgroundFillSymbol?.ValidateRequiredGeneratedChildren();
        LegendOptions?.ValidateRequiredGeneratedChildren();
        OthersCategory?.ValidateRequiredGeneratedChildren();
        Outline?.ValidateRequiredGeneratedChildren();
        if (VisualVariables is not null)
        {
            foreach (VisualVariable child in VisualVariables)
            {
                child.ValidateRequiredGeneratedChildren();
            }
        }
        base.ValidateRequiredGeneratedChildren();
    }
      
